/**
 * pwa/js/dexie.min.js - Autarker, robuster IndexedDB Wrapper mit Dexie.js kompatibler Fluent-API
 * Zero Dependencies / 100% Offline-First.
 */

(function(global) {
    class Table {
        constructor(dbInstance, name, schemaDef) {
            this.db = dbInstance;
            this.name = name;
            this.schemaDef = schemaDef;
            this.primKey = schemaDef.split(',')[0].trim().replace(/^(\+\+)?/, '');
        }

        _getStore(mode = 'readonly') {
            const tx = this.db._idb.transaction([this.name], mode);
            return tx.objectStore(this.name);
        }

        async get(key) {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readonly');
                const req = store.get(key);
                req.onsuccess = () => resolve(req.result || null);
                req.onerror = () => reject(req.error);
            });
        }

        async put(item) {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readwrite');
                const req = store.put(item);
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            });
        }

        async add(item) {
            return this.put(item);
        }

        async bulkPut(items = []) {
            await this.db._ensureOpen();
            if (!items || items.length === 0) return;
            return new Promise((resolve, reject) => {
                const tx = this.db._idb.transaction([this.name], 'readwrite');
                const store = tx.objectStore(this.name);
                items.forEach(item => store.put(item));
                tx.oncomplete = () => resolve();
                tx.onerror = () => reject(tx.error);
            });
        }

        async delete(key) {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readwrite');
                const req = store.delete(key);
                req.onsuccess = () => resolve();
                req.onerror = () => reject(req.error);
            });
        }

        async bulkDelete(keys = []) {
            await this.db._ensureOpen();
            if (!keys || keys.length === 0) return;
            return new Promise((resolve, reject) => {
                const tx = this.db._idb.transaction([this.name], 'readwrite');
                const store = tx.objectStore(this.name);
                keys.forEach(k => store.delete(k));
                tx.oncomplete = () => resolve();
                tx.onerror = () => reject(tx.error);
            });
        }

        async clear() {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readwrite');
                const req = store.clear();
                req.onsuccess = () => resolve();
                req.onerror = () => reject(req.error);
            });
        }

        async count() {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readonly');
                const req = store.count();
                req.onsuccess = () => resolve(req.result || 0);
                req.onerror = () => reject(req.error);
            });
        }

        async toArray() {
            await this.db._ensureOpen();
            return new Promise((resolve, reject) => {
                const store = this._getStore('readonly');
                const req = store.getAll();
                req.onsuccess = () => resolve(req.result || []);
                req.onerror = () => reject(req.error);
            });
        }

        where(indexOrField) {
            const table = this;
            return {
                equals(val) {
                    return {
                        async toArray() {
                            const all = await table.toArray();
                            return all.filter(item => item[indexOrField] === val);
                        },
                        async first() {
                            const items = await this.toArray();
                            return items[0] || null;
                        },
                        limit(num) {
                            return {
                                async toArray() {
                                    const all = await table.toArray();
                                    return all.filter(item => item[indexOrField] === val).slice(0, num);
                                }
                            };
                        }
                    };
                }
            };
        }
    }

    class Dexie {
        constructor(dbName) {
            this.name = dbName;
            this.schemaVersion = 1;
            this.storesDef = {};
            this._idb = null;
            this._openPromise = null;
        }

        version(ver) {
            this.schemaVersion = ver;
            return {
                stores: (schema) => {
                    this.storesDef = schema;
                    for (const tableName of Object.keys(schema)) {
                        this[tableName] = new Table(this, tableName, schema[tableName]);
                    }
                    return this;
                }
            };
        }

        async _ensureOpen() {
            if (this._idb) return this._idb;
            if (this._openPromise) return this._openPromise;

            this._openPromise = new Promise((resolve, reject) => {
                if (typeof indexedDB === 'undefined') {
                    return reject(new Error('IndexedDB ist in diesem Kontext nicht verfügbar.'));
                }
                const req = indexedDB.open(this.name, this.schemaVersion);

                req.onupgradeneeded = (e) => {
                    const db = req.result;
                    for (const [storeName, schemaStr] of Object.entries(this.storesDef)) {
                        const fields = schemaStr.split(',').map(s => s.trim()).filter(Boolean);
                        const primKey = fields[0].replace('++', '');
                        const autoIncrement = fields[0].startsWith('++');

                        let store;
                        if (!db.objectStoreNames.contains(storeName)) {
                            store = db.createObjectStore(storeName, { keyPath: primKey, autoIncrement });
                        } else {
                            store = req.transaction.objectStore(storeName);
                        }

                        // Indices anlegen
                        for (let i = 1; i < fields.length; i++) {
                            const f = fields[i].replace('&', '');
                            const unique = fields[i].startsWith('&');
                            if (!store.indexNames.contains(f)) {
                                store.createIndex(f, f, { unique });
                            }
                        }
                    }
                };

                req.onsuccess = () => {
                    this._idb = req.result;
                    resolve(this._idb);
                };

                req.onerror = () => {
                    this._openPromise = null;
                    reject(req.error);
                };
            });

            return this._openPromise;
        }

        async open() {
            return this._ensureOpen();
        }

        async close() {
            if (this._idb) {
                this._idb.close();
                this._idb = null;
                this._openPromise = null;
            }
        }

        async transaction(mode, ...args) {
            await this._ensureOpen();
            const fn = args[args.length - 1];
            if (typeof fn === 'function') {
                return fn();
            }
        }
    }

    global.Dexie = Dexie;
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Dexie;
    }
})(typeof self !== 'undefined' ? self : this);
